		wp_set_post_categories( $post_id, [ 1 ] );

		return "Created post '$slug' (ID $post_id). TODO: (1) Upload banner image, replace BANNER_IMAGE_URL_PLACEHOLDER. (2) Upload headshot, replace HEADSHOT_IMAGE_URL_PLACEHOLDER. (3) Set featured image. (4) Update related resource tiles once sinus chart + patient leaflet are uploaded.";
	},
];
